name: Test Analysis

on:
  workflow_run:
    workflows: ["Tests"]
    types:
      - completed

jobs:
  test-analysis:
    runs-on: ubuntu-latest
    steps:
      - name: Download test artifacts
        uses: actions/github-script@v7
        with:
          script: |
            const { data: artifacts } = await github.rest.actions.listWorkflowRunArtifacts({
              owner: context.repo.owner,
              repo: context.repo.repo,
              run_id: context.payload.workflow_run.id,
            });

            const artifact = artifacts.artifacts.find(artifact => artifact.name === "test-results");
            if (!artifact) {
              console.log("No test-results artifact found");
              return;
            }

            const { data: zip } = await github.rest.actions.downloadArtifact({
              owner: context.repo.owner,
              repo: context.repo.repo,
              artifact_id: artifact.id,
              archive_format: "zip",
            });

            const fs = require("fs");
            fs.writeFileSync("test-results.zip", Buffer.from(zip.data));

            const AdmZip = require("adm-zip");
            const zipFile = new AdmZip("test-results.zip");
            zipFile.extractAllTo("./test-results");

      - name: Publish test results
        uses: EnricoMi/publish-unit-test-result-action@v2
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          files: ./test-results/**/*.xml
          comment_title: Test Results
          comment_mode: replace
          fail_on: any
